+		/* this sysall will run twice
+		   (the tracer steps back the instruction pointer) */
+		rv = write(1, w1, sizeof(w1));
+		if (rv != 2) {
+			_exit(1);
+		}
+
+		/* run write unmodified */
+		rv = write(1, w3, sizeof(w3));
+		if (rv != 2) {
+			_exit(1);
+		}
+		_exit(0);
+	}
+
+	int status;
